symbols = [0x37, 0x21, 0x7d, 0x57, 0x34, 0x77, 0x30, 0x6a, 0x75, 0x36, 0x43, 0x3c, 0x6c, 0x62, 0x69, 0x76, 0x72, 0x5e, 0x5a, 0x65, 0x6d, 0x23, 0x2d, 0x63, 0x45, 0x3a, 0x35, 0x73, 0x48, 0x64, 0x24, 0x49, 0x38, 0x2a, 0x39, 0x40, 0x4a, 0x78, 0x51, 0x44, 0x7a, 0x52, 0x66, 0x4c, 0x70, 0x7e, 0x5f, 0x41, 0x29, 0x67, 0x3b, 0x68, 0x55, 0x46, 0x3f, 0x2e, 0x47, 0x5b, 0x4e, 0x6f, 0x50, 0x58, 0x7b, 0x71]
def decode(text, salt, size):
    ring = [0] * 64
    for cursor in range(64):
        ring[cursor] = symbols[(cursor + salt) % 32]
    values = [ring.index(c) for c in text[:(size * 8 + 5) // 6]]
    result = bytearray()
    for offset in range(0, len(values), 4):
        a, b, c, d = (values[offset:offset+4] + [0, 0, 0])[:4]
        result.append(((a << 2) | (b >> 4)) & 255)
        result.append(((b << 4) | (c >> 2)) & 255)
        result.append(((c << 6) | d) & 255)
    return bytes(result[:size])
